          "SELECT name FROM products WHERE name LIKE 'P%';",
          "SELECT name FROM products WHERE name LIKE '%phone%';",
          "SELECT name FROM products WHERE name LIKE 'P_n';",
          "SELECT name FROM products WHERE name LIKE 'head%';"
