          'SELECT o.id AS order_id, c.id AS customer_id, c.name AS customer',
          'FROM orders o',
          'JOIN customers c ON c.id = o.customer_id',
          'ORDER BY o.id;',
          'SELECT id FROM orders o JOIN customers c ON c.id = o.customer_id;'
