          "INSERT INTO monthly_sales VALUES ('2026-06-01', 12000), ('2026-07-01', 15000), ('2026-08-01', 13500), ('2026-09-01', 18000);",
          'SELECT month, amount,',
          '       lag(amount) OVER (ORDER BY month) AS previous,',
          '       amount - lag(amount) OVER (ORDER BY month) AS change',
